-- Backup generated on 2026-11-11 09:05:58

CREATE OR REPLACE PROCEDURE public.sp_seed_dev_parent_environment(IN p_user_id uuid, IN p_tenant_id uuid, IN p_email character varying, IN p_child_id uuid, IN p_security_stamp character varying)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_teacher_id UUID; BEGIN     -- 1. Ensure Sunita Patel exists in users     INSERT INTO users (         id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, password_hash, security_stamp, is_active     ) VALUES (         p_user_id, p_tenant_id, p_email, UPPER(p_email), TRUE, 'Sunita', 'Patel', 'Sunita Patel', '', p_security_stamp, TRUE     ) ON CONFLICT (id) DO UPDATE SET is_active = TRUE;      -- 2. Ensure mock child Aarav Patel exists     INSERT INTO children (id, tenant_id, first_name, last_name, date_of_birth, classroom_id, is_active)     VALUES (p_child_id, p_tenant_id, 'Aarav', 'Patel', '2023-01-15', '40000000-0000-0000-0000-000000000001', TRUE)     ON CONFLICT (id) DO UPDATE SET is_active = TRUE;      -- 3. Ensure family relationship links Sunita Patel to Aarav Patel     INSERT INTO family_relationships (id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at)     VALUES ('f0000000-0000-0000-0000-000000000001', p_tenant_id, p_child_id, p_user_id, 'Mother', TRUE, NOW(), 'Verified', NOW())     ON CONFLICT (child_id, user_id) DO NOTHING;      -- 4. Ensure person record exists for Family Profile     INSERT INTO persons (id, tenant_id, user_id, first_name, last_name, relationship, email, mobile_phone, preferred_contact_method, preferred_language, has_portal_access, receives_daily_updates, receives_photos)     VALUES ('70000000-0000-0000-0000-000000000001', p_tenant_id, p_user_id, 'Sunita', 'Patel', 'Mother', p_email, '416-555-0199', 'Mobile', 'English', TRUE, TRUE, TRUE)     ON CONFLICT (id) DO NOTHING;      -- 5. Ensure child guardian record exists     INSERT INTO child_guardians (id, tenant_id, child_id, person_id, relationship, is_primary, has_legal_custody, can_pickup, can_receive_information, can_authorize_medical_care)     VALUES ('80000000-0000-0000-0000-000000000001', p_tenant_id, p_child_id, '70000000-0000-0000-0000-000000000001', 'Mother', TRUE, TRUE, TRUE, TRUE, TRUE)     ON CONFLICT (child_id, person_id) DO NOTHING;      -- 6. Ensure sample journey entries and milestones exist     SELECT id INTO v_teacher_id FROM teachers WHERE tenant_id = p_tenant_id LIMIT 1;     IF v_teacher_id IS NOT NULL THEN         INSERT INTO child_journey_entries (id, tenant_id, child_id, teacher_id, journey_type, title, observation, child_voice, observation_date, is_parent_visible, parent_visibility_status)         VALUES ('90000000-0000-0000-0000-000000000001', p_tenant_id, p_child_id, v_teacher_id, 'Art & Sensory', 'Exploring Watercolor Rainbows', 'Aarav mixed colors and identified secondary hues.', 'Look, I made green!', NOW(), TRUE, 'Approved')         ON CONFLICT (id) DO NOTHING;          INSERT INTO child_milestones (id, tenant_id, child_id, teacher_id, title, description, milestone_date, parent_visible, status)         VALUES ('91000000-0000-0000-0000-000000000001', p_tenant_id, p_child_id, v_teacher_id, 'Collaborative Tower Building', 'Constructed a stable 12-block tower with peers demonstrating turn-taking.', NOW(), TRUE, 'Active')         ON CONFLICT (id) DO NOTHING;     END IF; END; $procedure$ ;
